void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  float d = length(fragCoord - iMouse.xy);
  vec3 col = vec3(smoothstep(30.0, 28.0, d)) * vec3(1.0, 0.4, 0.2);
  col += vec3(0.0, 0.0, step(0.0, iMouse.z)) * 0.5 * uv.x;
  col += vec3(0.0, step(0.0, iMouse.w) * 0.4, 0.0);
  fragColor = vec4(col + 0.08, 1.0);
}
